args.sparql:
SELECT DISTINCT ?artist ?artistLabel WHERE {
  dbr:Me_and_Bobby_McGee dbo:artist ?artist .
  OPTIONAL { ?artist rdfs:label ?artistLabel . FILTER(lang(?artistLabel) = "en") }
}

SELECT DISTINCT ?artist ?child ?childLabel WHERE {
  dbr:Me_and_Bobby_McGee dbo:artist ?artist .
  {
    ?artist dbo:child ?child .
  } UNION {
    ?artist dbo:children ?child .
  } UNION {
    ?artist dbp:children ?child .
  } UNION {
    ?artist dbp:child ?child .
  }
  OPTIONAL { ?child rdfs:label ?childLabel . FILTER(lang(?childLabel) = "en") }
}

